[CmdletBinding()]
param([string]$BundlesDirectory='ES/Output/WebPageStudio/bundles')
$ErrorActionPreference='Stop';$OutputEncoding=[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';$dir=[IO.Path]::GetFullPath((Join-Path $root $BundlesDirectory));if(-not $dir.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'BundlesDirectory must remain under project root.'};$batch=Join-Path $root 'ES/Automation/WebPageStudio/Test-ESWebPageStudioLocaleBundleFreshness.ps1';$rows=[System.Collections.Generic.List[object]]::new();foreach($manifest in @(Get-ChildItem -LiteralPath $dir -Recurse -Filter manifest.json -File)){$r=& $batch -ManifestPath $manifest.FullName|ConvertFrom-Json;$rows.Add([pscustomobject]@{bundle=$manifest.Directory.Name;manifest=$manifest.FullName.Replace($root,'').Replace('\','/');status=$r.status;targetCount=$r.targetCount;passedCount=$r.passedCount;failedCount=$r.failedCount})};$passed=@($rows|? status -eq 'passed').Count;$stale=@($rows|? status -ne 'passed').Count;$sourceHashes=[ordered]@{};foreach($source in @('Test-ESWebPageStudioAllBundlesFreshness.ps1','Test-ESWebPageStudioLocaleBundleFreshness.ps1','Test-ESWebPageStudioFreshness.ps1')){$sourceHashes[$source]=(Get-FileHash -LiteralPath (Join-Path $root ('ES/Automation/WebPageStudio/'+$source)) -Algorithm SHA256).Hash.ToLowerInvariant()};[pscustomobject]@{schemaVersion=1;recordType='WebPageStudioAllBundlesFreshnessReceipt';status=if($stale -eq 0 -and $rows.Count -gt 0){'passed'}else{'stale'};bundleCount=$rows.Count;passedBundleCount=$passed;staleBundleCount=$stale;bundles=$rows;sourceHashes=$sourceHashes;evidenceLevel='S1';runtimeStatus='runtime-not-run';claimsNotProven=@('Historical bundle audit does not rewrite stale artifacts or prove browser, backend, Unity, or production runtime behavior.') }|ConvertTo-Json -Depth 8
